function cleanHtmlForTelegram(htmlString) {
    const allowedTags = ['b', 'strong', 'i', 'em', 'u', 's', 'code', 'pre', 'blockquote', 'tg-spoiler', 'a'];
    let cleaned = htmlString;
    cleaned = cleaned.replace(/<(?!\/?(?:b|strong|i|em|u|s|code|pre|blockquote|tg-spoiler|a)(\s|>))[^>]*>/gi, '');
    cleaned = cleaned.replace(/<a(?!\s+href="[^"]*")[^>]*>(.*?)<\/a>/gi, '$1');
    return cleaned;
}

function splitTelegramMessage(text, maxLength = 4096) {
    if (text.length <= maxLength) {
        return [text];
    }

    const messages = [];
    let currentChunk = '';
    const parts = text.split(/(<\/blockquote>|<\/pre>|<\/code>|\n\n)/);

    for (const part of parts) {
        if (!part) continue;
        if (currentChunk.length + part.length > maxLength) {
            if (currentChunk.trim()) {
                messages.push(currentChunk.trim());
            }
            currentChunk = part;
        } else {
            currentChunk += part;
        }
    }

    if (currentChunk.trim()) {
        messages.push(currentChunk.trim());
    }

    return messages;
}

try {
    const geminiOutput = $input.first().json.output;
    const cleaned = cleanHtmlForTelegram(geminiOutput);
    const messageParts = splitTelegramMessage(cleaned);

    console.log(`Обработано частей: ${messageParts.length}`);
    return { output: messageParts };

} catch (error) {
    console.error('Ошибка:', error);
    return { output: [`❌ Ошибка: ${error.message}`] };
}

// Замена Markdown на HTML + исправление звездочек в спойлерах
function convertMarkdownToHtml(text) {
    // Заменяем **текст** на <b>текст</b>
    text = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

    // Заменяем *текст* на <i>текст</i> (но осторожно, чтобы не затронуть списки)
    text = text.replace(/\*([^*\n]+?)\*/g, '<i>$1</i>');

    // Исправляем звездочки в списках внутри спойлеров
    text = text.replace(/\*\s+<b>/g, '• <b>');
    text = text.replace(/\*\s+([^<])/g, '• $1');

    // Исправляем остальные звездочки в начале строк (списки)
    text = text.replace(/^\*\s+/gm, '• ');

    // ДОБАВЬТЕ ЭТУ СТРОКУ: Принудительно добавляем expandable к blockquote
    text = text.replace(/<blockquote>/g, '<blockquote expandable>');

    return text;
}

try {
    const inputText = $input.first().json.output;
    const convertedText = convertMarkdownToHtml(inputText);

    console.log('Конвертация выполнена успешно');
    return [{ json: { output: convertedText } }];

} catch (error) {
    console.error('Ошибка конвертации:', error);
    return [{ json: { output: inputText || 'Ошибка' } }];
}

// Получаем все входные элементы
const items = $input.all();

// Обрабатываем каждый элемент
const processedItems = items.map(item => {
  let transcript = item.json.transcript || [];

  // Проверяем, что это массив объектов
  if (Array.isArray(transcript) && transcript.length > 0) {
    // Форматируем каждый элемент: [timestamp] speaker: text
    const formattedTranscript = transcript.map(t => {
      // Обработка timestamp: если объект, стрингифицируем или берём поле
      let timestamp = t.timestamp;
      if (typeof timestamp === 'object') {
        timestamp = timestamp.text || timestamp.start || JSON.stringify(timestamp);
      } else if (!timestamp) {
        timestamp = '';
      }

      // Обработка speaker: если объект, берём name или стрингифицируем
      let speaker = t.speaker;
      if (typeof speaker === 'object') {
        speaker = speaker.name || speaker.display_name || JSON.stringify(speaker);
      } else if (!speaker) {
        speaker = 'Unknown';
      }

      // Обработка text: если объект, берём text или стрингифицируем
      let text = t.text;
      if (typeof text === 'object') {
        text = text.content || JSON.stringify(text);
      } else if (!text) {
        text = '';
      }

      return `[${timestamp}] ${speaker}: ${text}`;
    }).join('\n');

    // Добавляем форматированную строку в JSON
    item.json.transcriptFormatted = formattedTranscript;
  } else {
    // Если не массив или пусто, добавляем пустую строку
    item.json.transcriptFormatted = '';
  }

  return item;
});

return processedItems;

