const msg = $json.message || {};
const file = msg.voice || msg.audio || msg.document || msg.video || msg.video_note || null;
const fileName = file?.file_name || msg.document?.file_name || null;
const mimeType = file?.mime_type || null;
const ext = fileName && fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : null;

let inputType = 'unknown';
if (msg.text) inputType = 'text';
else if (msg.voice) inputType = 'voice';
else if (msg.audio) inputType = 'audio';
else if (msg.document) {
  const audioExts = ['m4a', 'mp3', 'wav', 'aac', 'ogg'];
  inputType = audioExts.includes(ext || '') ? 'document_audio' : 'document_other';
} else if (msg.video_note) inputType = 'video_note';
else if (msg.video) inputType = 'video';

return [{ json: {
  chat_id: msg.chat?.id,
  message_id: msg.message_id,
  user_id: msg.from?.id,
  username: msg.from?.username || '',
  first_name: msg.from?.first_name || '',
  input_type: inputType,
  text_input: msg.text || msg.caption || '',
  file_id: file?.file_id || null,
  file_name: fileName,
  mime_type: mimeType,
  file_ext: ext,
  raw_message: msg
}}];

const meta = $('Detect Input Type').first().json;
const item = $input.first();
if (!item.binary || !item.binary.data) throw new Error('Binary file not found');
item.binary.data.fileName = meta.file_name || item.binary.data.fileName || `input.${meta.file_ext || 'bin'}`;
item.binary.data.mimeType = meta.mime_type || item.binary.data.mimeType || 'application/octet-stream';
return [{ json: { ...meta, media_ready: true }, binary: { data: item.binary.data } }];

const meta = $('Detect Input Type').first().json;
const stt = $input.first().json;
const transcript = stt.text || stt.output || stt.transcript || '';
return [{ json: { ...meta, transcript_text: transcript, text_for_agents: transcript || meta.text_input || '' } }];
